class Solution {
  public int minXor(int[] nums, int k) {
    int n = nums.length;
    int[] pre = new int[n + 1];
    for (int i = 0; i < n; i++) pre[i + 1] = pre[i] ^ nums[i];
    int INF = Integer.MAX_VALUE;
    int[] prev = new int[n + 1];
    for (int i = 1; i <= n; i++) prev[i] = pre[i];
    for (int j = 2; j <= k; j++) {
      int[] cur = new int[n + 1];
      java.util.Arrays.fill(cur, INF);
      for (int i = j; i <= n; i++) {
        for (int t = j - 1; t < i; t++) {
          int v = Math.max(prev[t], pre[i] ^ pre[t]);
          if (v < cur[i]) cur[i] = v;
        }
      }
      prev = cur;
    }
    return prev[n];
  }
}
